WITH remaining_keys AS (SELECT id, product_id FROM order_items EXCEPT DISTINCT SELECT id, product_id FROM order_items WHERE quantity >= 8), reconciled AS (SELECT s.* FROM order_items s INNER JOIN remaining_keys k ON s.id = k.id AND s.product_id = k.product_id) SELECT order_id, AVG(unit_price) AS avg_unit_price, BIT_AND(quantity) AS quantity_bit_and, ROUND(AVG(quantity), 2) AS avg_quantity, CORR(quantity, unit_price) AS corr_quantity_unit_price, BIT_OR(quantity) AS quantity_bit_or FROM reconciled GROUP BY order_id;
